def selftest_report(w):
    """Kurzer Startest (für den automatischen Windows-Build): schreibt das Ergebnis in eine Datei."""
    import tempfile
    lines = []
    try:
        assert parse_channel("https://www.youtube.com/watch?v=dQw4w9WgXcQ") == "youtube:video/dQw4w9WgXcQ"
        assert parse_channel("twitch:name") == "twitch:name"
        lines.append("Kanal-Erkennung ok")
        lines.append(f"Audio-Geräte: {len(audio_sinks())}")
        lines.append(f"fehlende Programme: {missing_tools() or 'keine'}")
        try:
            mpv_request(b"{}\n", timeout=0.2)
        except OSError:
            lines.append("IPC: erwartete Fehlermeldung ohne laufenden mpv ok")
        pm = w.gif_label.pixmap()
        assert pm is not None and not pm.isNull()
        lines.append("GIF wird angezeigt ok")
        result = "OK\n" + "\n".join(lines)
    except Exception as ex:
        result = f"FEHLER: {ex!r}\n" + "\n".join(lines)
    (Path(tempfile.gettempdir()) / "livelistener-selftest.txt").write_text(result, encoding="utf-8")
    return result.startswith("OK")


if __name__ == "__main__":
    if IS_WIN:  # Windows-Skalierung (z. B. 4K mit 150 %) übernehmen
        QApplication.setAttribute(Qt.ApplicationAttribute.AA_EnableHighDpiScaling, True)
        QApplication.setAttribute(Qt.ApplicationAttribute.AA_UseHighDpiPixmaps, True)
        if hasattr(Qt, "HighDpiScaleFactorRoundingPolicy"):
            QApplication.setHighDpiScaleFactorRoundingPolicy(Qt.HighDpiScaleFactorRoundingPolicy.PassThrough)
    app = QApplication(sys.argv)
    app.setStyle("Fusion")
    app.setApplicationName("livelistener")
    app.setDesktopFileName("livelistener")  # passt zum Menüeintrag (Wayland-Icon)
    app.setWindowIcon(load_app_icon())
    w = Window()
    w.show()
    if SELFTEST:
        QTimer.singleShot(1500, lambda: app.exit(0 if selftest_report(w) else 1))
    else:
        def warn_missing():
            missing = missing_tools()
            local_uv = Path.home() / ".local" / "bin" / "uv"
            if (not IS_WIN and "streamlink" in missing
                    and (shutil.which("pipx") or shutil.which("uv") or local_uv.is_file())):
                # Die App richtet streamlink im Hintergrund selbst ein (siehe update_streamlink)
                missing.remove("streamlink")
                w.tray.showMessage("livelistener", "streamlink wird eingerichtet. Das dauert beim ersten Start "
                                   "etwa eine Minute.", QSystemTrayIcon.MessageIcon.Information, 8000)
            if missing:
                hint = ("Windows: Der Ordner mpv bzw. streamlink muss neben livelistener.exe liegen, oder installiere sie mit\n"
                        "winget install shinchiro.mpv Streamlink.Streamlink"
                        if IS_WIN else "Bitte installieren: sudo apt install mpv pipx (siehe README).")
                QMessageBox.warning(w, "livelistener", f"Es fehlt: {', '.join(missing)}\n\n{hint}\n\n"
                                    f"Liegt das Programm woanders, trage den Pfad in {CONFIG} ein "
                                    "(mpv_path bzw. streamlink_path).")
        QTimer.singleShot(800, warn_missing)
    app.aboutToQuit.connect(w.stop)
    signal.signal(signal.SIGINT, lambda *a: w.quit_app())  # Strg+C im Terminal
    sig_timer = QTimer()
    sig_timer.start(500)  # lässt Python Signale verarbeiten
    sig_timer.timeout.connect(lambda: None)
    sys.exit(app.exec())
